package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/satori/go.uuid"
)

// Define your struct here (example):
type MyStruct struct {
	Field1 int `json:"field1"`
	Field2 string `json:"field2"`
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run parser.go [GoFile] [StructName]")
		os.Exit(1)
	}

	goFileName := os.Args[1]
	structName := os.Args[2]

	// Read the entire content of the Go file
	content, err := ioutil.ReadFile(goFileName)
	if err != nil {
		fmt.Printf("Error reading file %s: %v\n", goFileName, err)
		return
	}

	// Parse the JSON structure if necessary (not required since we're directly using struct fields)
	var myStruct MyStruct
	json.Unmarshal(content, &myStruct)

	// Generate Avro schema
	schemaString, err := generateAvroSchema(structName, &myStruct)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	// Write the generated Avro schema to a file
	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", structName), []byte(schemaString), 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema to %s.avsc: %v\n", structName, err)
		return
	}
}

// Helper function to generate Avro schema based on struct fields
func generateAvroSchema(name string, obj interface{}) ([]byte, error) {
	avroSchema, err := json.Marshal(obj)
	if err != nil {
		return nil, fmt.Errorf("marshaling object into Avro schema failed: %w", err)
	}

	// Assuming the first field's type is the root element type
	rootType := avroSchema[0].(string)

	// Generate schema definition
	schema := fmt.Sprintf(`{
	"namespace": "your.namespace",
	"type": "record",
	"name": "%s",
	"fields": [%s]
}`, name, fmt.Sprintf(`{"name":"%s","type":"%s"}`, name, rootType))

	return []byte(schema), nil
}
```

### Explanation:
- **Reading the Source File**: The program reads the specified Go source file.
- **Parsing Struct Fields**: Since we don't need to parse JSON directly from the struct fields, the `generateAvroSchema` function assumes that the struct has at least one field whose type will serve as the root element type in the Avro schema.
- **Generating Schema**: The function creates an Avro schema definition using the provided struct's fields and writes it to a file named after the struct.

